<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('appointments.manage');
$id=max(0,(int)($_GET['id']??$_POST['id']??0));$channel=(string)($_GET['channel']??$_POST['channel']??'email');if(!in_array($channel,['email','whatsapp'],true))$channel='email';
$stmt=db()->prepare("SELECT a.*,c.company_name,c.email client_email,c.whatsapp client_whatsapp,CONCAT(p.first_name,' ',COALESCE(p.last_name,'')) contact_name,p.email contact_email,p.whatsapp contact_whatsapp,u.name assigned_name FROM appointments a LEFT JOIN clients c ON c.id=a.client_id LEFT JOIN contacts p ON p.id=a.contact_id LEFT JOIN users u ON u.id=a.assigned_to WHERE a.id=?");$stmt->execute([$id]);$row=$stmt->fetch();if(!$row){http_response_code(404);exit('Cita no encontrada.');}
$pageTitle='Enviar invitación';$errors=[];$defaultRecipient=$channel==='email'?($row['contact_email']?:$row['client_email']):($row['contact_whatsapp']?:$row['client_whatsapp']);$date=(new DateTimeImmutable($row['start_at']))->format('d/m/Y H:i');$end=$row['end_at']?(new DateTimeImmutable($row['end_at']))->format('H:i'):'';$who=trim((string)($row['contact_name']?:$row['company_name']?:'Cliente'));
$defaultMessage="Hola {$who},\n\nTe invitamos a la reunión: {$row['title']}\nFecha y hora: {$date}".($end?" a {$end}":'')."\nEnlace: ".($row['meeting_url']?:$row['external_booking_url']?:'Por confirmar')."\n\nSaludos,\nSÓCRATES ONE · Creative Studio";
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$recipient=trim((string)($_POST['recipient']??''));$message=trim((string)($_POST['message']??''));if($recipient==='')$errors[]='Indica el destinatario.';if($message==='')$errors[]='Escribe el mensaje.';if($channel==='email'&&!filter_var($recipient,FILTER_VALIDATE_EMAIL))$errors[]='El email no es válido.';if(!$errors){if($channel==='email'){$html='<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;border:1px solid #dbe6ed;border-radius:14px;overflow:hidden"><div style="background:#003f70;color:#fff;padding:24px"><h2 style="margin:0">Invitación a reunión</h2></div><div style="padding:24px"><h3 style="color:#003f70">'.e($row['title']).'</h3><p><strong>Fecha:</strong> '.e($date.($end?' a '.$end:'')).'</p>'.($row['meeting_url']?'<p><a style="display:inline-block;background:#ff5300;color:#fff;text-decoration:none;padding:12px 18px;border-radius:4px" href="'.e($row['meeting_url']).'">ENTRAR A LA REUNIÓN</a></p>':'').'<p style="white-space:pre-line">'.nl2br(e($message)).'</p></div></div>';$result=send_system_email($recipient,'Invitación: '.$row['title'],$html);}else{$result=send_whatsapp_cloud_message($recipient,$message);}if($result['success']){log_activity('Invitación de reunión enviada',$row['client_id']?:null,null,$channel.' · '.$row['title']);flash('success','Invitación enviada por '.($channel==='email'?'email':'WhatsApp').'.');redirect('appointments.php');}$errors[]='No se pudo enviar: '.($result['error']??'Error desconocido.');}}
require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><div class="dashboard-grid"><form method="post" class="panel"><div class="panel-header"><div><h2>Enviar por <?=$channel==='email'?'email':'WhatsApp'?></h2><span class="table-sub">Revisa el destinatario y el contenido antes de enviar.</span></div><a class="btn btn-light" href="appointment_form.php?id=<?=$id?>">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="channel" value="<?=e($channel)?>"><label>Destinatario *<input name="recipient" required value="<?=e($_POST['recipient']??$defaultRecipient)?>" placeholder="<?=$channel==='email'?'cliente@empresa.com':'+56 9...'?>"></label><label class="full">Mensaje<textarea name="message" rows="12" required><?=e($_POST['message']??$defaultMessage)?></textarea></label><div class="full form-actions"><button class="btn btn-primary">ENVIAR INVITACIÓN</button></div></div></form><aside class="panel"><div class="panel-header"><h2>Resumen</h2></div><div class="panel-body details-grid"><div class="detail"><small>Reunión</small><strong><?=e($row['title'])?></strong></div><div class="detail"><small>Fecha</small><strong><?=e($date.($end?' a '.$end:''))?></strong></div><div class="detail"><small>Cliente</small><strong><?=e($row['company_name']?:'—')?></strong></div><div class="detail"><small>Enlace</small><strong><?=e($row['meeting_url']?:'Por confirmar')?></strong></div></div></aside></div><?php require __DIR__.'/includes/footer.php';?>
